package gg.cinco.client;

import net.minecraft.client.texture.NativeImage;
import net.minecraft.util.Identifier;
import java.util.Base64;

/** Runtime texture built from the user-provided Star Client logo. */
public final class StarLogoTexture {
    private static Identifier id;
    private static final String DATA="";
    private StarLogoTexture(){}
    public static Identifier get(){
        if(id!=null)return id;
        try{id=StarTextureCompat.register("star_logo",NativeImage.read(Base64.getDecoder().decode(DATA)));}
        catch(Exception ignored){id=Identifier.of("minecraft","textures/misc/unknown_server.png");}
        return id;
    }
}
